import assetIntegrity from './asset-integrity.mjs';

// Leaflet pack: portable runtime gotchas for the Leaflet web-mapping library
// (map init, tile layers, markers/divIcons, and CDN-loaded plugins like
// Leaflet.markercluster). Most are runtime behaviours with no repo-state
// signature and stay prose; the CDN wiring of the assets themselves is written
// into the HTML, so it converts. Fingerprinted by an actual Leaflet reference: a
// CDN asset (leaflet@ / leaflet.js / leaflet.css) in HTML, or a Leaflet API call
// site (L.map( / L.tileLayer( / L.markerClusterGroup() ) in source. The marker
// only *suspects* the pack; declaring it is the project's call, like every pack.

const LEAFLET_ASSET = /\bleaflet(\.js|\.css|@[\d.]|[-/]dist)/i;
const LEAFLET_API = /\bL\.(map|tileLayer|markerClusterGroup)\s*\(/;
const SOURCE = /\.(html?|mjs|cjs|jsx?|tsx?)$/;

export default {
  id: 'leaflet',
  ruleRoutingGuidance: {
    belongs: 'map rendering with the Leaflet library — map init options, tile layers, markers and divIcons, CDN plugin pinning',
    excludes: 'generic HTML markup rules — that is html; non-map dependency policy belongs to node',
  },
  badge: 'badge.svg',
  marker: 'a Leaflet reference (CDN asset, or an L.map/L.tileLayer/L.markerClusterGroup call) in HTML/JS source',
  detect: (ctx) =>
    ctx.tracked.some((f) => {
      if (!SOURCE.test(f)) return false;
      const text = ctx.read(f);
      return text !== null && (LEAFLET_ASSET.test(text) || LEAFLET_API.test(text));
    }),
  prose: 'RULES.md',
  worldRules: [assetIntegrity],
};
==========
import { finding } from '../../engine/checks/helpers/findings.mjs';

// Converted from the leaflet prose: every Leaflet asset loaded from a CDN — the
// core bundle AND every plugin — must be version-pinned and carry an SRI hash
// with `crossorigin`. The trap the prose names is a partial job: the core
// `leaflet@1.9.4` script gets the full treatment and a plugin's `<script>` is
// left bare, so one un-hashed third-party URL still executes with the page's
// full authority. That is a static signature in the HTML, so it converts.
//
// PARSED, NOT GREPPED (the skill's rule): grep for `unpkg.com` or `integrity`
// answers the wrong question. The rule is about one *tag* — a `<script>`/`<link>`
// whose own URL is a remote Leaflet asset — so the scan reads each tag's own
// attributes and judges only those. A locally vendored `js/leaflet.js`, a
// preconnect to the CDN host, and a Leaflet URL sitting in ordinary page text are
// all none of this rule's business. HTML comments are stripped first, so an
// example of the bad wiring written in a comment never fires it.

const HTML = /\.html?$/i;
const TAG = /<(script|link)\b([^>]*)>/gi;
const REMOTE = /^(?:https?:)?\/\//i;
const LEAFLET = /leaflet/i;
// An exact pin is a `major.minor…` version reached by the URL's own delimiters —
// `leaflet@1.9.4/…` (unpkg/jsdelivr), `/leaflet/1.9.4/…` (cdnjs), `leaflet-1.9.4.js`
// (a self-hosted mirror). A bare `@latest`, a major-only `@1`, or a version-less
// path matches none of them.
const PINNED = /[@/-]\d+\.\d+[\w.+-]*(?:$|[/?#])/;
const SRI = /^sha(?:256|384|512)-\S+/;

// `source` with its HTML comments blanked out, newlines kept so line numbers
// don't shift.
function stripHtmlComments(source) {
  return source.replace(/<!--[\s\S]*?-->/g, (m) => m.replace(/[^\n]/g, ' '));
}

// The tag's own attributes as a lowercased-name map. A valueless attribute
// (`crossorigin`) maps to '' — present, which is what the rule asks.
function attributes(text) {
  const attrs = {};
  const re = /([a-zA-Z_:][-\w:.]*)(?:\s*=\s*("[^"]*"|'[^']*'|[^\s"'>]+))?/g;
  for (let m = re.exec(text); m; m = re.exec(text)) {
    const raw = m[2] ?? '';
    attrs[m[1].toLowerCase()] =
      raw.startsWith('"') || raw.startsWith("'") ? raw.slice(1, -1) : raw;
  }
  return attrs;
}

const rule = {
  id: 'leaflet/asset-integrity',
  severity: 'blocking',
  description:
    'Every CDN-loaded Leaflet asset — core bundle and plugins alike — is version-pinned and carries an SRI hash with crossorigin',
  doc: 'packs/leaflet/RULES.md',
  why: 'an un-pinned or un-hashed third-party script runs with the page\'s full authority, so whatever the CDN serves tomorrow is what your users execute — and the hole is usually a plugin tag left bare beside a correctly wired core bundle',

  run(ctx) {
    const out = [];
    for (const file of ctx.files) {
      if (!HTML.test(file)) continue;
      const raw = ctx.read(file);
      if (raw === null || !LEAFLET.test(raw)) continue;
      const src = stripHtmlComments(raw);
      TAG.lastIndex = 0;
      for (let m = TAG.exec(src); m; m = TAG.exec(src)) {
        const attrs = attributes(m[2]);
        const url = m[1].toLowerCase() === 'script' ? attrs.src : attrs.href;
        if (!url || !REMOTE.test(url) || !LEAFLET.test(url)) continue;

        const missing = [];
        if (!PINNED.test(url)) missing.push('an exact version pin (leaflet@1.9.4, never @latest)');
        if (!SRI.test(attrs.integrity ?? '')) missing.push('integrity="sha256-…"');
        if (attrs.crossorigin === undefined) missing.push('crossorigin');
        if (missing.length === 0) continue;

        out.push(finding(rule, {
          file,
          line: src.slice(0, m.index).split('\n').length,
          what: `loads the Leaflet asset ${url} without ${missing.join(' / ')}`,
          fix: `pin the exact version in the URL and carry integrity="sha256-…" + crossorigin="" on this <${m[1].toLowerCase()}> — the plugin tags too, not just the core bundle`,
        }));
      }
    }
    return out;
  },
};

export default rule;
==========TEST
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { makeRepo, cleanup } from '../../engine-tests/helpers.mjs';
import { buildContext } from '../../engine/checks/helpers/repo-context.mjs';
import assetIntegrity from '../../packs/leaflet/asset-integrity.mjs';

const run = (rule, root) => rule.run(buildContext({ root, mode: 'all' }));

const page = (body) => makeRepo({ changed: { 'index.html': body } });

const CORE_JS =
  '<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin=""></script>';
const CORE_CSS =
  '<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=" crossorigin="" />';

test('leaflet/asset-integrity: flags the plugin tag left bare beside a wired core bundle', () => {
  const root = page(`<head>
${CORE_CSS}
${CORE_JS}
<script src="https://unpkg.com/leaflet.markercluster@1.5.3/dist/leaflet.markercluster.js"></script>
</head>
`);
  try {
    const findings = run(assetIntegrity, root);
    assert.equal(findings.length, 1);
    assert.equal(findings[0].severity, 'blocking');
    assert.equal(findings[0].file, 'index.html');
    assert.equal(findings[0].line, 4);
    assert.match(findings[0].what, /leaflet\.markercluster/);
    assert.match(findings[0].what, /integrity/);
    assert.match(findings[0].what, /crossorigin/);
    // Pinned, so only the two missing attributes are named.
    assert.doesNotMatch(findings[0].what, /version pin/);
  } finally { cleanup(root); }
});

test('leaflet/asset-integrity: flags an unpinned URL, naming the pin as what is missing', () => {
  const root = page(`<script src="https://unpkg.com/leaflet@latest/dist/leaflet.js" integrity="sha256-abc" crossorigin=""></script>
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/leaflet/dist/leaflet.css" integrity="sha512-abc" crossorigin>
`);
  try {
    const findings = run(assetIntegrity, root);
    assert.equal(findings.length, 2);
    for (const f of findings) assert.match(f.what, /version pin/);
  } finally { cleanup(root); }
});

test('leaflet/asset-integrity: clean when core and plugin are both pinned + hashed', () => {
  const root = page(`<head>
${CORE_CSS}
${CORE_JS}
<script src="https://unpkg.com/leaflet.markercluster@1.5.3/dist/leaflet.markercluster.js" integrity="sha256-WL3FnpU4nH8HnEXHzMKnUCFHrPZ0J5MZ0RGGHhPTQ+E=" crossorigin=""></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.js" integrity="sha512-abc" crossorigin="anonymous"></script>
</head>
`);
  try {
    assert.deepEqual(run(assetIntegrity, root), []);
  } finally { cleanup(root); }
});

// Helpers for checks that scan source *code* for a forbidden token (a banned
// API, an impure import, a DOM specific). Such a check must see code, not
// prose: a comment or a doc-string that merely *names* `chrome.storage` or
// `fetch(` is describing the code, not doing it, and matching it is a false
// positive that fails the build over an English sentence. Strip comments first.

// Return `source` with its JS/TS comments removed, leaving everything else —
// including string and template literals — byte-for-byte intact. String-aware
// on purpose: a `//` inside "https://…" is not a comment, and dropping the rest
// of that line would corrupt real code (and could hide a genuine violation that
// follows on the same line). Regex literals are treated as code and preserved.
// Newlines inside block comments are kept so line numbers don't shift.
export function stripComments(source) {
  let out = '';
  let state = 'code'; // code | line | block | sq | dq | tpl
  for (let i = 0; i < source.length; i++) {
    const c = source[i];
    const c2 = source[i + 1];
    if (state === 'code') {
      if (c === '/' && c2 === '/') { state = 'line'; i++; continue; }
      if (c === '/' && c2 === '*') { state = 'block'; i++; continue; }
      if (c === "'") state = 'sq';
      else if (c === '"') state = 'dq';
      else if (c === '`') state = 'tpl';
      out += c;
    } else if (state === 'line') {
      if (c === '\n') { state = 'code'; out += c; }
    } else if (state === 'block') {
      if (c === '*' && c2 === '/') { state = 'code'; i++; }
      else if (c === '\n') out += c;
    } else {
      // Inside a string/template literal: copy through until the matching quote,
      // honoring backslash escapes so an escaped quote doesn't end it early.
      out += c;
      if (c === '\\') { out += c2 ?? ''; i++; }
      else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
        state = 'code';
      }
    }
  }
  return out;
}
=== findings helper ===
export function finding(rule, { file, line = null, what, fix, why = null, severity = null }) {
  return {
    rule: rule.id,
    severity: severity || rule.severity,
    file,
    line,
    what,
    why: why || rule.why,
    fix,
    doc: rule.doc,
  };
}

// Severity overrides then acceptances, in that order, so an acceptance is judged
// against the rule the project actually runs. A reasonless acceptance is itself
// a blocking finding: the reason string is what makes the decision reviewable.
export function applyConfig(findings, config) {
  const out = [];
  for (let f of findings) {
    const override = config.rules[f.rule];
    if (override === 'advisory' || override === 'blocking') f = { ...f, severity: override };
    // A path ending in "/" accepts a whole subtree; otherwise the match is exact.
    const acceptance = config.accept.find(
      (a) => a.rule === f.rule &&
        (!a.path || a.path === f.file || (a.path.endsWith('/') && f.file.startsWith(a.path)))
    );
    if (acceptance) {
      if (typeof acceptance.reason === 'string' && acceptance.reason.trim()) continue;
      out.push({
        rule: 'config',
        severity: 'blocking',
        file: '.claudinite-checks.json',
        line: null,
        what: `acceptance for ${f.rule}${acceptance.path ? ` on ${acceptance.path}` : ''}${acceptance.pack ? ` (on the "${acceptance.pack}" pack entry)` : ''} has no reason`,
        why: 'the reason string is what makes an accepted violation reviewable',
        fix: 'add a non-empty "reason" to the acceptance entry',
        doc: 'engine/checks/README.md',
      });
    }
    out.push(f);
  }
  return out;
}

export function render(f) {
  const loc = f.line ? `${f.file}:${f.line}` : f.file;
  return [
    `[${f.severity.toUpperCase()}] ${f.rule}  ${loc}`,
    `  ${f.what}`,
    ...(f.why ? [`  Why: ${f.why}`] : []),
    `  Fix: ${f.fix}`,
    ...(f.doc ? [`  More: ${f.doc}`] : []),
  ].join('\n');
}

# packs/ — the corpus content, active by declaration

Each `packs/<name>/` bundles a pack's **prose** (`RULES.md`, injected at session start when the pack is active), its **checks** (run at every Stop), and its **bundled skills** (`<pack>/skills/`, mounted at session start). **No pack is active by default** — every pack, the `basics` baseline included, activates only when declared in `.claudinite-checks.json` (bootstrap's `--init` seeds `basics` plus the fingerprinted technology packs; the nightly baselining backfills the explicit `basics` declaration into existing consumers). Discovery is structural — any `packs/<name>/pack.mjs` is a pack, and that manifest is the pack's index: what it owns, the checks it runs in each scope, the skills it bundles. A pack's `README.md` is **optional** and carries only what the manifest cannot — provenance, design rationale, an index of its prose. A README that restates the manifest is duplication with a drift risk, and several had already drifted.

